/**
 * wp-color-picker-alpha
 * Adds alpha channel support to the WordPress color picker.
 * Based on the wp-color-picker-alpha project (MIT License).
 */
(function($) {
	if (!$.wp || !$.wp.wpColorPicker) return;

	var ColorPicker = $.wp.wpColorPicker;

	$.widget('wp.wpColorPicker', ColorPicker, {
		_addListeners: function() {
			if (!this.options.palettes && this.element.data('alphaEnabled')) {
				this._super();
				return;
			}
			ColorPicker.prototype._addListeners.call(this);
		},

		_create: function() {
			ColorPicker.prototype._create.call(this);

			var self = this,
				el = self.element;

			if (!el.data('alphaEnabled')) return;

			var $wrap = self.wrap,
				$result = $wrap.find('.wp-color-result'),
				$picker = $wrap.find('.wp-picker-holder'),
				$iris = el.iris('instance');

			// Extend iris to support rgba.
			if ($iris) {
				var origHue = $iris._change;
				$iris._change = function() {
					origHue.apply(this, arguments);
					var color = el.val();
					$result.css('background-color', color);
				};
			}

			// Allow rgba input.
			el.off('change.wpColorPicker').on('change.wpColorPicker', function() {
				var val = $(this).val();
				if (val.match(/^rgba?\(/)) {
					$result.css('background-color', val);
				}
			});

			// Add alpha slider.
			var alphaVal = 100;
			var match = el.val().match(/rgba\(\s*\d+\s*,\s*\d+\s*,\s*\d+\s*,\s*([\d.]+)\s*\)/);
			if (match) {
				alphaVal = Math.round(parseFloat(match[1]) * 100);
			}

			var $alphaWrap = $('<div class="atx-alpha-wrap" style="padding:0 12px 12px;"></div>');
			var $alphaLabel = $('<label style="display:block;font-size:11px;margin-bottom:4px;">Opacity: <span class="atx-alpha-val">' + alphaVal + '%</span></label>');
			var $alphaSlider = $('<input type="range" min="0" max="100" value="' + alphaVal + '" style="width:100%;margin:0;" class="atx-alpha-slider" />');

			$alphaWrap.append($alphaLabel).append($alphaSlider);
			$picker.find('.iris-picker').append($alphaWrap);

			$alphaSlider.on('input change', function() {
				var alpha = parseInt($(this).val(), 10) / 100;
				$alphaWrap.find('.atx-alpha-val').text($(this).val() + '%');

				var current = el.iris('color');
				if (!current) return;

				// Parse hex to rgba.
				var hex = current.replace('#', '');
				if (hex.length === 3) {
					hex = hex[0]+hex[0]+hex[1]+hex[1]+hex[2]+hex[2];
				}
				var r = parseInt(hex.substring(0,2), 16);
				var g = parseInt(hex.substring(2,4), 16);
				var b = parseInt(hex.substring(4,6), 16);

				var rgba = 'rgba(' + r + ',' + g + ',' + b + ',' + alpha.toFixed(2) + ')';
				el.val(rgba).trigger('change');
				$result.css('background-color', rgba);
			});

			// On iris color change, rebuild rgba with current alpha.
			el.on('irischange', function(e, data) {
				var alpha = parseInt($alphaSlider.val(), 10) / 100;
				if (alpha < 1) {
					var hex = data.color.toString().replace('#', '');
					var r = parseInt(hex.substring(0,2), 16);
					var g = parseInt(hex.substring(2,4), 16);
					var b = parseInt(hex.substring(4,6), 16);
					var rgba = 'rgba(' + r + ',' + g + ',' + b + ',' + alpha.toFixed(2) + ')';
					el.val(rgba);
					$result.css('background-color', rgba);
				}
			});

			// Set initial background.
			$result.css('background-color', el.val());
		}
	});
})(jQuery);
